// ---------------------------------------------------------------------------
// The SLH-DSA public key's two bare ASN.1 structures — `decode_der2key.c:62-79`.
// ---------------------------------------------------------------------------

/// `typedef struct { ASN1_OBJECT *oid; } BARE_ALGOR;`.
#[repr(C)]
struct BareAlgor {
    /// `ASN1_OBJECT *oid`.
    oid: *mut Asn1Object,
}

/// `typedef struct { BARE_ALGOR algor; ASN1_BIT_STRING *pubkey; } BARE_PUBKEY;`.
#[repr(C)]
struct BarePubkey {
    /// `BARE_ALGOR algor` — embedded, hence [`ASN1_TFLG_EMBED`].
    algor: BareAlgor,
    /// `ASN1_BIT_STRING *pubkey`.
    pubkey: *mut Asn1String,
}

/// `const ASN1_ITEM *BARE_ALGOR_it(void)` — the `ASN1_SEQUENCE_END(BARE_ALGOR)` accessor.
unsafe extern "C" fn bare_algor_it() -> *const c_void {
    (&BARE_ALGOR_ITEM as *const Asn1Item).cast()
}

/// `BARE_ALGOR_seq_tt` — `ASN1_SIMPLE(BARE_ALGOR, oid, ASN1_OBJECT)`.
static BARE_ALGOR_TT: [Asn1Template; 1] = [Asn1Template {
    flags: 0,
    tag: 0,
    offset: core::mem::offset_of!(BareAlgor, oid) as core::ffi::c_ulong,
    field_name: c"oid".as_ptr(),
    item: ASN1_OBJECT_it as *mut c_void,
}];

/// `BARE_ALGOR_it`'s descriptor — `ASN1_SEQUENCE_END(BARE_ALGOR)`.
static BARE_ALGOR_ITEM: Asn1Item = Asn1Item {
    itype: ASN1_ITYPE_SEQUENCE,
    utype: V_ASN1_SEQUENCE as c_long,
    templates: BARE_ALGOR_TT.as_ptr(),
    tcount: 1,
    funcs: ptr::null(),
    size: size_of::<BareAlgor>() as c_long,
    sname: c"BARE_ALGOR".as_ptr(),
};

/// `BARE_PUBKEY_seq_tt` — `ASN1_EMBED(BARE_PUBKEY, algor, BARE_ALGOR)` and
/// `ASN1_SIMPLE(BARE_PUBKEY, pubkey, ASN1_BIT_STRING)`.
static BARE_PUBKEY_TT: [Asn1Template; 2] = [
    Asn1Template {
        flags: ASN1_TFLG_EMBED,
        tag: 0,
        offset: core::mem::offset_of!(BarePubkey, algor) as core::ffi::c_ulong,
        field_name: c"algor".as_ptr(),
        item: bare_algor_it as *mut c_void,
    },
    Asn1Template {
        flags: 0,
        tag: 0,
        offset: core::mem::offset_of!(BarePubkey, pubkey) as core::ffi::c_ulong,
        field_name: c"pubkey".as_ptr(),
        item: ASN1_BIT_STRING_it as *mut c_void,
    },
];

/// `BARE_PUBKEY_it`'s descriptor — `ASN1_SEQUENCE_END(BARE_PUBKEY)`.
static BARE_PUBKEY_ITEM: Asn1Item = Asn1Item {
    itype: ASN1_ITYPE_SEQUENCE,
    utype: V_ASN1_SEQUENCE as c_long,
    templates: BARE_PUBKEY_TT.as_ptr(),
    tcount: 2,
    funcs: ptr::null(),
    size: size_of::<BarePubkey>() as c_long,
    sname: c"BARE_PUBKEY".as_ptr(),
};

