/// `int check_key_fn(void *, struct der2key_ctx_st *ctx)`.
type CheckKeyFn = unsafe fn(*mut c_void, *mut Der2keyCtx) -> c_int;
/// `void adjust_key_fn(void *, struct der2key_ctx_st *ctx)`.
type AdjustKeyFn = unsafe fn(*mut c_void, *mut Der2keyCtx);
/// `void free_key_fn(void *)`.
type FreeKeyFn = unsafe fn(*mut c_void);
/// `void *d2i_PKCS8_fn(const unsigned char **, long, struct der2key_ctx_st *)`.
type D2iPkcs8Fn = unsafe fn(*mut *const c_uchar, c_long, *mut Der2keyCtx) -> *mut c_void;
/// `void *d2i_PUBKEY_fn(const unsigned char **, long, struct der2key_ctx_st *)`.
type D2iPubkeyFn = unsafe fn(*mut *const c_uchar, c_long, *mut Der2keyCtx) -> *mut c_void;
/// `typedef void *key_from_pkcs8_t(const PKCS8_PRIV_KEY_INFO *, OSSL_LIB_CTX *, const char *)`.
type KeyFromPkcs8Fn =
    unsafe extern "C" fn(*const c_void, *mut c_void, *const c_char) -> *mut c_void;

/// `struct keytype_desc_st` — `decode_der2key.c:81-120`.
struct KeytypeDesc {
    /// `const char *keytype_name` — the implementation key type, and the announced `data-type`.
    keytype_name: *const c_char,
    /// `const OSSL_DISPATCH *fns` — the key type's own keymgmt table (to pilfer the export from).
    keymgmt: *const OsslDispatch,
    /// `const char *structure_name` — declared in the authority and read nowhere; kept for shape.
    #[allow(dead_code)]
    structure_name: *const c_char,
    /// `int evp_type` — the `EVP_PKEY_*` type the row insists on.
    evp_type: c_int,
    /// `int selection_mask` — `does_selection`'s answer for the row.
    selection_mask: c_int,
    /// `d2i_of_void *d2i_private_key`.
    d2i_private_key: Option<D2iOfVoid>,
    /// `d2i_of_void *d2i_public_key`.
    d2i_public_key: Option<D2iOfVoid>,
    /// `d2i_of_void *d2i_key_params`.
    d2i_key_params: Option<D2iOfVoid>,
    /// `d2i_PKCS8_fn *d2i_PKCS8`.
    d2i_pkcs8: Option<D2iPkcs8Fn>,
    /// `d2i_PUBKEY_fn *d2i_PUBKEY`.
    d2i_pubkey: Option<D2iPubkeyFn>,
    /// `check_key_fn *check_key`.
    check_key: Option<CheckKeyFn>,
    /// `adjust_key_fn *adjust_key`.
    adjust_key: Option<AdjustKeyFn>,
    /// `free_key_fn *free_key`.
    free_key: Option<FreeKeyFn>,
}

// SAFETY: a `KeytypeDesc` this module builds is a `static` compiled from constants — every field is
// written once by the loader and never again — so sharing `&KeytypeDesc` across threads exposes no
// data race. The fields are scalars and raw pointers to statics; the fn pointers are immutable.
unsafe impl Sync for KeytypeDesc {}

/// `struct der2key_ctx_st` — `decode_der2key.c:125-133`.
struct Der2keyCtx {
    /// `PROV_CTX *provctx`.
    provctx: *mut c_void,
    /// `char propq[OSSL_MAX_PROPQUERY_SIZE]`.
    propq: [c_char; OSSL_MAX_PROPQUERY_SIZE],
    /// `const struct keytype_desc_st *desc`.
    desc: &'static KeytypeDesc,
    /// `int selection` — the selection passed to `der2key_decode`.
    selection: c_int,
    /// `unsigned int flag_fatal : 1` — set by nothing in the authority's unit; kept for shape.
    flag_fatal: u32,
}

// ---------------------------------------------------------------------------
// `der2key_set_ctx_params` — the machine-generated parser (`decode_der2key.c:190-236`).
// ---------------------------------------------------------------------------

/// `struct der2key_set_ctx_params_st` — the one field the generated parser fills.
struct Der2keySetCtxParams {
    /// `OSSL_PARAM *propq`.
    propq: *const OsslParam,
}

/// `static int der2key_set_ctx_params_decoder(const OSSL_PARAM *p, struct
/// der2key_set_ctx_params_st *r)` — the `paramnames.pm` expansion. A repeated `properties` raises
/// `PROV_R_REPEATED_PARAMETER` at the second occurrence and refuses.
///
/// # Safety
/// `params` must be NULL or a `key`-terminated array.
unsafe fn der2key_set_ctx_params_decoder(params: *const OsslParam) -> Option<Der2keySetCtxParams> {
    let mut r = Der2keySetCtxParams { propq: ptr::null() };

    if params.is_null() {
        return Some(r);
    }

    // SAFETY: the walk stops at the NULL key.
    unsafe {
        let mut p = params;
        while !(*p).key.is_null() {
            if CStr::from_ptr((*p).key).to_bytes() == b"properties" {
                if !r.propq.is_null() {
                    raise_site(&err_sites::PROV_DECODE_DER2KEY_202);
                    return None;
                }
                r.propq = p;
            }
            p = p.add(1);
        }
    }

    Some(r)
}

/// `static const OSSL_PARAM der2key_set_ctx_params_list[]` — `decode_der2key.c:179`.
static DER2KEY_SET_CTX_PARAMS_LIST: [OsslParam; 2] =
    [param_utf8_string(OSSL_DECODER_PARAM_PROPERTIES), END];

/// `static const OSSL_PARAM *der2key_settable_ctx_params(void *provctx)` — `:216-219`.
///
/// # Safety
/// The decoder `settable_ctx_params` dispatch contract; `_provctx` is ignored.
unsafe extern "C" fn der2key_settable_ctx_params(_provctx: *mut c_void) -> *const OsslParam {
    DER2KEY_SET_CTX_PARAMS_LIST.as_ptr()
}

/// `static int der2key_set_ctx_params(void *vctx, const OSSL_PARAM params[])` — `:221-236`.
///
/// # Safety
/// The decoder `set_ctx_params` dispatch contract.
unsafe extern "C" fn der2key_set_ctx_params(vctx: *mut c_void, params: *const OsslParam) -> c_int {
    let ctx = vctx.cast::<Der2keyCtx>();

    // SAFETY: `ctx` is the caller's context and `params` is NULL or a terminated array.
    unsafe {
        if ctx.is_null() {
            return 0;
        }
        let Some(p) = der2key_set_ctx_params_decoder(params) else {
            return 0;
        };

        let mut str_ = (*ctx).propq.as_mut_ptr();
        if !p.propq.is_null()
            && OSSL_PARAM_get_utf8_string(p.propq, &mut str_, OSSL_MAX_PROPQUERY_SIZE) == 0
        {
            return 0;
        }
    }
    1
}

// ---------------------------------------------------------------------------
// The PKCS#8 helper and the engine — `decode_der2key.c:137-155`, `:165-403`.
// ---------------------------------------------------------------------------

/// `static void *der2key_decode_p8(const unsigned char **input_der, long input_der_len,
/// struct der2key_ctx_st *ctx, key_from_pkcs8_t *key_from_pkcs8)` — `:137-155`.
///
/// # Safety
/// `der` is the caller's readable cursor; `ctx` is the caller's context.
unsafe fn der2key_decode_p8(
    der: *mut *const c_uchar,
    der_len: c_long,
    ctx: *mut Der2keyCtx,
    key_from_pkcs8: KeyFromPkcs8Fn,
) -> *mut c_void {
    let mut alg: *const X509Algor = ptr::null();
    let mut key: *mut c_void = ptr::null_mut();

    // SAFETY: `der` is the caller's cursor and `der_len` its length.
    let p8inf = unsafe { d2i_PKCS8_PRIV_KEY_INFO(ptr::null_mut(), der, der_len) };
    // SAFETY: `p8inf` is NULL or live; `alg` is this frame's out-parameter.
    let have_key = !p8inf.is_null()
        && unsafe {
            PKCS8_pkey_get0(
                ptr::null_mut(),
                ptr::null_mut(),
                ptr::null_mut(),
                &mut alg,
                p8inf,
            )
        } != 0;
    if have_key {
        // SAFETY: `alg` is live past the guard and `ctx` is the caller's.
        let (nid, evp_type) = unsafe { (OBJ_obj2nid((*alg).algorithm), (*ctx).desc.evp_type) };
        if nid == evp_type || (nid == NID_X9_62_id_ecPublicKey && evp_type == NID_sm2) {
            // SAFETY: `p8inf` is live; `ctx`'s provctx/propq are the engine's.
            key = unsafe {
                key_from_pkcs8(
                    p8inf.cast(),
                    prov_libctx_of((*ctx).provctx),
                    (*ctx).propq.as_ptr(),
                )
            };
        }
    }
    // SAFETY: `p8inf` is NULL or live and this call owns it.
    unsafe { PKCS8_PRIV_KEY_INFO_free(p8inf) };

    key
}

/// `static struct der2key_ctx_st *der2key_newctx(void *provctx, const struct keytype_desc_st
/// *desc)` — `:165-175`.
///
/// # Safety
/// `provctx` is the live provider context; `desc` a live row descriptor.
unsafe fn der2key_newctx(provctx: *mut c_void, desc: &'static KeytypeDesc) -> *mut c_void {
    // SAFETY: the allocator takes the file/line for its mdbg record only.
    let ctx = CRYPTO_zalloc(size_of::<Der2keyCtx>(), ptr::null(), 0).cast::<Der2keyCtx>();
    if !ctx.is_null() {
        // SAFETY: `ctx` is a fresh zeroed allocation this frame owns.
        unsafe {
            (*ctx).provctx = provctx;
            (*ctx).desc = desc;
        }
    }
    ctx.cast::<c_void>()
}

/// `static void der2key_freectx(void *vctx)` — `:205-210`.
///
/// # Safety
/// The decoder `freectx` dispatch contract.
unsafe extern "C" fn der2key_freectx(vctx: *mut c_void) {
    // SAFETY: `vctx` is NULL or the context `der2key_newctx` allocated.
    unsafe { CRYPTO_free(vctx.cast::<c_void>(), ptr::null(), 0) };
}

/// `static int der2key_check_selection(int selection, const struct keytype_desc_st *desc)` —
/// `:212-244`. The selections are levels: the first of the three the caller asks for is answered
/// by whether the row's mask carries it, and an empty selection is accepted so the caller may guess.
fn der2key_check_selection(selection: c_int, desc: &KeytypeDesc) -> c_int {
    let checks = [
        OSSL_KEYMGMT_SELECT_PRIVATE_KEY,
        OSSL_KEYMGMT_SELECT_PUBLIC_KEY,
        OSSL_KEYMGMT_SELECT_ALL_PARAMETERS,
    ];

    if selection == 0 {
        return 1;
    }
    for check in checks {
        let check1 = (selection & check) != 0;
        let check2 = (desc.selection_mask & check) != 0;
        if check1 {
            return c_int::from(check2);
        }
    }
    0
}

/// Raise `msg` through `site`, the `ERR_raise_data` form of a site whose text interpolates a name.
///
/// # Safety
/// Nothing: the message is NUL-terminated here.
unsafe fn raise_msg(site: &err_sites::ErrSite, msg: String) {
    let mut buf = msg.into_bytes();
    buf.push(0);
    // SAFETY: `buf` is NUL-terminated just above.
    unsafe { raise_site_data(site, buf.as_ptr().cast()) };
}

/// `static int der2key_decode(void *vctx, OSSL_CORE_BIO *cin, int selection, OSSL_CALLBACK
/// *data_cb, void *data_cbarg, OSSL_PASSPHRASE_CALLBACK *pw_cb, void *pw_cbarg)` — `:246-382`.
///
/// # Safety
/// The decoder `decode` dispatch contract.
#[allow(clippy::too_many_arguments)] // mirrors the authority's signature exactly
#[allow(unused_assignments)] // the `ok` slot is written before it is read on every path
unsafe extern "C" fn der2key_decode(
    vctx: *mut c_void,
    cin: *mut c_void,
    selection: c_int,
    data_cb: Option<OsslCallback>,
    data_cbarg: *mut c_void,
    _pw_cb: Option<OsslPassphraseCallback>,
    _pw_cbarg: *mut c_void,
) -> c_int {
    let ctx = vctx.cast::<Der2keyCtx>();
    let mut der: *mut c_uchar = ptr::null_mut();
    let mut der_len: c_long = 0;
    let mut key: *mut c_void = ptr::null_mut();
    let mut ok: c_int = 0;
    let mut fatal = false;

    // SAFETY: `ctx` is the caller's live decoder context.
    let desc = unsafe { &(*ctx).desc };
    // SAFETY: `ctx` is live and the field is this context's own.
    unsafe { (*ctx).selection = selection };
    let orig_selection = selection;
    let mut selection = selection;
    if selection == 0 {
        selection = desc.selection_mask;
    }
    if (selection & desc.selection_mask) == 0 {
        // SAFETY: a compile-time-constant site.
        unsafe { raise_site(&err_sites::PROV_DECODE_DER2KEY_300) };
        return 0;
    }

    'flow: {
        // SAFETY: `ctx`'s provctx is live and `cin` is the core BIO this decode owns.
        ok = unsafe { ossl_read_der((*ctx).provctx, cin, &mut der, &mut der_len) };
        if ok == 0 {
            break 'flow; // `next:`
        }

        ok = 0; // Assume that we fail.

        ERR_set_mark();
        if (selection & OSSL_KEYMGMT_SELECT_PRIVATE_KEY) != 0 {
            let mut derp = der as *const c_uchar;
            if let Some(f) = desc.d2i_pkcs8 {
                // SAFETY: `f` is the row's d2i; `derp`/`der_len`/`ctx` are this frame's.
                key = unsafe { f(&mut derp, der_len, ctx) };
                // SAFETY: `ctx` is live and the field is this context's own.
                if unsafe { (*ctx).flag_fatal } != 0 {
                    ERR_clear_last_mark();
                    fatal = true;
                    break 'flow;
                }
            } else if let Some(f) = desc.d2i_private_key {
                // SAFETY: `f` is the row's d2i and the arguments are this frame's.
                key = unsafe { f(ptr::null_mut(), &mut derp, der_len) };
            }
            if key.is_null() && orig_selection != 0 {
                ERR_clear_last_mark();
                break 'flow; // `next:`
            }
        }
        if key.is_null() && (selection & OSSL_KEYMGMT_SELECT_PUBLIC_KEY) != 0 {
            let mut derp = der as *const c_uchar;
            if let Some(f) = desc.d2i_pubkey {
                // SAFETY: `f` is the row's d2i and the arguments are this frame's.
                key = unsafe { f(&mut derp, der_len, ctx) };
            } else if let Some(f) = desc.d2i_public_key {
                // SAFETY: `f` is the row's d2i and the arguments are this frame's.
                key = unsafe { f(ptr::null_mut(), &mut derp, der_len) };
            }
            if key.is_null() && orig_selection != 0 {
                ERR_clear_last_mark();
                break 'flow; // `next:`
            }
        }
        if key.is_null() && (selection & OSSL_KEYMGMT_SELECT_ALL_PARAMETERS) != 0 {
            let mut derp = der as *const c_uchar;
            if let Some(f) = desc.d2i_key_params {
                // SAFETY: `f` is the row's d2i and the arguments are this frame's.
                key = unsafe { f(ptr::null_mut(), &mut derp, der_len) };
            }
            if key.is_null() && orig_selection != 0 {
                ERR_clear_last_mark();
                break 'flow; // `next:`
            }
        }
        if key.is_null() {
            ERR_clear_last_mark();
        } else {
            ERR_pop_to_mark();
        }

        // The last-minute key-type check, and the provider-specific adjustment.
        if !key.is_null() {
            if let Some(f) = desc.check_key {
                // SAFETY: `f` is the row's own check over `key`.
                if unsafe { f(key, ctx) } == 0 {
                    if let Some(fr) = desc.free_key {
                        // SAFETY: `key` is live and the row's own free owns it.
                        unsafe { fr(key) };
                    }
                    key = ptr::null_mut();
                }
            }
        }
        if !key.is_null() {
            if let Some(f) = desc.adjust_key {
                // SAFETY: `f` is the row's own adjustment over `key`.
                unsafe { f(key, ctx) };
            }
        }
    }

    if fatal {
        if let Some(fr) = desc.free_key {
            // SAFETY: `key` is NULL or live and the row's own free owns it.
            unsafe { fr(key) };
        }
        // SAFETY: `der` is NULL or the buffer `ossl_read_der` allocated.
        unsafe { CRYPTO_free(der.cast::<c_void>(), ptr::null(), 0) };
        return ok;
    }

    // `next:` — "empty handed" is not an error.
    ok = 1;

    // SAFETY: `der` is NULL or the buffer the read allocated and this call owns it.
    unsafe { CRYPTO_free(der.cast::<c_void>(), ptr::null(), 0) };
    der = ptr::null_mut();

    if !key.is_null() {
        let mut params: [OsslParam; 4] = [END; 4];
        let mut object_type: c_int = OSSL_OBJECT_PKEY;
        let keytype_name = desc.keytype_name;
        // SAFETY: `keytype_name` is NUL-terminated and `key` is the row's own EC key or another.
        let data_type = if unsafe { CStr::from_ptr(keytype_name) }.to_bytes() == b"EC"
            && (unsafe { EC_KEY_get_flags(key.cast::<EcKey>()) } & EC_FLAG_SM2_RANGE) != 0
        {
            c"SM2".as_ptr()
        } else {
            keytype_name
        };

        // SAFETY: every constructor is called with this frame's buffers/slots.
        unsafe {
            params[0] = OSSL_PARAM_construct_int(OSSL_OBJECT_PARAM_TYPE, &mut object_type);
            params[1] = OSSL_PARAM_construct_utf8_string(
                OSSL_OBJECT_PARAM_DATA_TYPE,
                data_type.cast_mut(),
                0,
            );
            params[2] = OSSL_PARAM_construct_octet_string(
                OSSL_OBJECT_PARAM_REFERENCE,
                (&mut key as *mut *mut c_void).cast(),
                size_of::<*mut c_void>(),
            );
            params[3] = OSSL_PARAM_construct_end();
        }

        // SAFETY: `cb` is the framework's callback and every argument is this frame's.
        ok = match data_cb {
            // SAFETY: `cb` is the framework's callback and the arguments are this frame's.
            Some(cb) => unsafe { cb(params.as_ptr(), data_cbarg) },
            None => 0,
        };
    }

    // `end:`
    if let Some(fr) = desc.free_key {
        // SAFETY: `key` is NULL or live and the row's own free owns it.
        unsafe { fr(key) };
    }
    // SAFETY: `der` is NULL after `next:` and this call owns whatever is left.
    unsafe { CRYPTO_free(der.cast::<c_void>(), ptr::null(), 0) };

    ok
}

/// `static int der2key_export_object(void *vctx, const void *reference, size_t reference_sz,
/// OSSL_CALLBACK *export_cb, void *export_cbarg)` — `:384-403`.
///
/// # Safety
/// The decoder `export_object` dispatch contract.
unsafe extern "C" fn der2key_export_object(
    vctx: *mut c_void,
    reference: *const c_void,
    reference_sz: usize,
    export_cb: Option<OsslCallback>,
    export_cbarg: *mut c_void,
) -> c_int {
    let ctx = vctx.cast::<Der2keyCtx>();
    // SAFETY: `ctx` is live; the keymgmt export slot is the row's own.
    let export = unsafe { ossl_prov_get_keymgmt_export((*ctx).desc.keymgmt) };

    if reference_sz == size_of::<*mut c_void>() && export.is_some() {
        // SAFETY: `ctx` is live.
        let mut selection = unsafe { (*ctx).selection };
        if selection == 0 {
            selection = OSSL_KEYMGMT_SELECT_ALL;
        }
        // SAFETY: the reference's contents is the address of the decoded object, and the export is
        // the caller's own live keymgmt export.
        let keydata = unsafe { *(reference as *const *mut c_void) };
        return match export {
            // SAFETY: `f` is a live keymgmt export and the arguments are the caller's.
            Some(f) => unsafe { f(keydata, selection, export_cb, export_cbarg) },
            None => 0,
        };
    }
    0
}

