/// `D2I_PUBKEY_NOCTX` — `decode_der2key.c:405-411` — call `f(NULL, der, der_len)`.
macro_rules! d2i_pubkey_noctx {
    ($name:ident, $f:path) => {
        /// A `D2I_PUBKEY_NOCTX`-shaped forwarder to `$f`.
        ///
        /// # Safety
        /// `der` is the caller's readable cursor and `der_len` its length.
        unsafe fn $name(
            der: *mut *const c_uchar,
            der_len: c_long,
            _ctx: *mut Der2keyCtx,
        ) -> *mut c_void {
            // SAFETY: `$f` takes the NULL first argument and the caller's cursor.
            unsafe { $f(ptr::null_mut(), der, der_len).cast() }
        }
    };
}

