/// `static int ec_check(void *key, struct der2key_ctx_st *ctx)` — `:491-504`.
///
/// # Safety
/// `key` is an `EC_KEY *`; `ctx` is the caller's.
unsafe fn ec_check(key: *mut c_void, ctx: *mut Der2keyCtx) -> c_int {
    // SAFETY: `key` is the row's EC key.
    let sm2 = (unsafe { EC_KEY_get_flags(key.cast::<EcKey>()) } & EC_FLAG_SM2_RANGE) != 0;
    // SAFETY: `ctx` is live.
    let evp_type = unsafe { (*ctx).desc.evp_type };
    if sm2 {
        c_int::from(evp_type == EVP_PKEY_SM2_V || evp_type == NID_X9_62_id_ecPublicKey)
    } else {
        c_int::from(evp_type != EVP_PKEY_SM2_V)
    }
}

/// `static int rsa_check(void *key, struct der2key_ctx_st *ctx)` — `:917-936`.
///
/// # Safety
/// `key` is an `RSA *`; `ctx` is the caller's.
unsafe fn rsa_check(key: *mut c_void, ctx: *mut Der2keyCtx) -> c_int {
    // SAFETY: `key` is the row's RSA object.
    let flags = unsafe { RSA_test_flags(key.cast(), RSA_FLAG_TYPE_MASK) };
    // SAFETY: `ctx` is live.
    let evp_type = unsafe { (*ctx).desc.evp_type };
    let valid = match flags {
        RSA_FLAG_TYPE_RSA => evp_type == EVP_PKEY_RSA_V,
        RSA_FLAG_TYPE_RSASSAPSS => evp_type == EVP_PKEY_RSA_PSS_V,
        _ => false,
    };
    // SAFETY: `key` is live and the row's own.
    c_int::from(valid && unsafe { ossl_rsa_check_factors(key.cast()) } != 0)
}

