/// `ml_kem_d2i_PKCS8`/`ml_kem_d2i_PUBKEY`/`ml_dsa_*` — `:594-617`, `:956-978` — advance the cursor
/// on success, exactly as the authority's `*der += der_len` does.
macro_rules! ml_codec_d2i {
    ($name:ident, $f:path, $t:ty) => {
        /// An ML-* `d2i` forwarder that advances the cursor on success.
        ///
        /// # Safety
        /// `der` is the caller's readable cursor; `ctx` is the caller's.
        unsafe fn $name(
            der: *mut *const c_uchar,
            der_len: c_long,
            ctx: *mut Der2keyCtx,
        ) -> *mut c_void {
            // SAFETY: `der` is the caller's readable cursor and `ctx` is live.
            let key = unsafe {
                $f(
                    *der,
                    der_len as c_int,
                    (*ctx).desc.evp_type,
                    (*ctx).provctx.cast::<ProvCtx>(),
                    (*ctx).propq.as_ptr(),
                )
            };
            if !key.is_null() {
                // SAFETY: the cursor advances by the length the caller passed, as the authority's
                // `*der += der_len` does.
                unsafe { *der = (*der).add(der_len as usize) };
            }
            key.cast::<$t>().cast()
        }
    };
}

