/// `static void *slh_dsa_d2i_PKCS8(const uint8_t **der, long der_len, struct der2key_ctx_st
/// *ctx)` — `:652-688`.
///
/// # Safety
/// `der` is the caller's readable cursor; `ctx` is the caller's.
#[allow(unused_assignments)] // `p8inf` is cleared to NULL, then written by the decode below
unsafe fn slh_dsa_d2i_pkcs8(
    der: *mut *const c_uchar,
    der_len: c_long,
    ctx: *mut Der2keyCtx,
) -> *mut c_void {
    let mut key: *mut SlhDsaKey = ptr::null_mut();
    let mut ret: *mut SlhDsaKey = ptr::null_mut();
    let mut p8inf: *mut Pkcs8PrivKeyInfo = ptr::null_mut();
    let mut p: *const c_uchar = ptr::null();
    let mut alg: *const X509Algor = ptr::null();
    let mut plen: c_int = 0;
    let mut ptype: c_int = 0;

    'body: {
        // SAFETY: `der` is the caller's cursor and `der_len` its length.
        p8inf = unsafe { d2i_PKCS8_PRIV_KEY_INFO(ptr::null_mut(), der, der_len) };
        // SAFETY: `p8inf` is NULL or live; `p`/`plen`/`alg` are this frame's out-parameters.
        let have_key = !p8inf.is_null()
            && unsafe { PKCS8_pkey_get0(ptr::null_mut(), &mut p, &mut plen, &mut alg, p8inf) } != 0;
        if !have_key {
            break 'body;
        }

        // Algorithm parameters must be absent.
        // SAFETY: `alg` is live past the guard; `ptype` is this frame's.
        unsafe { X509_ALGOR_get0(ptr::null_mut(), &mut ptype, ptr::null_mut(), alg) };
        if ptype != V_ASN1_UNDEF {
            // SAFETY: `ctx`'s name is NUL-terminated.
            let name = unsafe { CStr::from_ptr((*ctx).desc.keytype_name) }.to_string_lossy();
            // SAFETY: the message is NUL-terminated by `raise_msg`.
            unsafe {
                raise_msg(
                    &err_sites::PROV_DECODE_DER2KEY_699,
                    format!("unexpected parameters with a PKCS#8 {name} private key"),
                )
            };
            break 'body;
        }
        // SAFETY: `alg` is live; `ctx` is live.
        if unsafe { OBJ_obj2nid((*alg).algorithm) } != unsafe { (*ctx).desc.evp_type } {
            break 'body;
        }
        // SAFETY: `ctx`'s libctx/propq/name are the engine's.
        key = unsafe {
            ossl_slh_dsa_key_new(
                prov_libctx_of((*ctx).provctx),
                (*ctx).propq.as_ptr(),
                (*ctx).desc.keytype_name,
            )
        };
        if key.is_null() {
            break 'body;
        }

        // SAFETY: `key` is live and `p`/`plen` are the PKCS8's own key material.
        if unsafe { ossl_slh_dsa_set_priv(key, p, plen as usize) } == 0 {
            break 'body;
        }
        ret = key;
    }

    // SAFETY: `p8inf` is NULL or live and this call owns it.
    unsafe { PKCS8_PRIV_KEY_INFO_free(p8inf) };
    if ret.is_null() {
        // SAFETY: `key` is NULL or live and this call owns it.
        unsafe { ossl_slh_dsa_key_free(key) };
    }
    ret.cast::<c_void>()
}

/// Free a `BARE_PUBKEY` and its owned fields, the authority's `err:` cleanup.
///
/// # Safety
/// `spki` is NULL or the frame's own zalloc'd structure.
unsafe fn free_bare_pubkey(spki: *mut BarePubkey) {
    // SAFETY: `spki` is NULL or this frame's own; its fields are the item machinery's.
    unsafe {
        if !spki.is_null() {
            ASN1_OBJECT_free((*spki).algor.oid);
            ASN1_BIT_STRING_free((*spki).pubkey);
            CRYPTO_free(spki.cast::<c_void>(), ptr::null(), 0);
        }
    }
}

/// `static ossl_inline void *slh_dsa_d2i_PUBKEY(const uint8_t **der, long der_len, struct
/// der2key_ctx_st *ctx)` — `:690-772`.
///
/// # Safety
/// `der` is the caller's readable cursor; `ctx` is the caller's.
#[allow(unused_assignments)] // `spki` is cleared to NULL, then written by the decode below
unsafe fn slh_dsa_d2i_pubkey(
    der: *mut *const c_uchar,
    der_len: c_long,
    ctx: *mut Der2keyCtx,
) -> *mut c_void {
    // SAFETY: `ctx`'s provctx is live.
    let libctx = unsafe { prov_libctx_of((*ctx).provctx) };
    // SAFETY: `ctx`'s propq/name are the engine's.
    let ret: *mut SlhDsaKey =
        unsafe { ossl_slh_dsa_key_new(libctx, (*ctx).propq.as_ptr(), (*ctx).desc.keytype_name) };
    if ret.is_null() {
        return ptr::null_mut();
    }
    // SAFETY: `ret` is live.
    let len = unsafe { ossl_slh_dsa_key_get_pub_len(ret) };
    let mut spki: *mut BarePubkey = ptr::null_mut();
    // SAFETY: `der` is the caller's readable cursor.
    let mut end: *const c_uchar = unsafe { *der };

    // The DER encoding of an SLH-DSA public key prepends 18 bytes to the encoded public key.
    if der_len != 18 + len as c_long {
        // SAFETY: `ctx`'s name is NUL-terminated.
        let name = unsafe { CStr::from_ptr((*ctx).desc.keytype_name) }.to_string_lossy();
        // SAFETY: the message is NUL-terminated by `raise_msg`.
        unsafe {
            raise_msg(
                &err_sites::PROV_DECODE_DER2KEY_751,
                format!(
                    "unexpected {name} public key length: {der_len} != {}",
                    18 + len as c_long
                ),
            )
        };
        // SAFETY: `ret` is live and this call owns it.
        unsafe { ossl_slh_dsa_key_free(ret) };
        return ptr::null_mut();
    }

    // SAFETY: the allocator takes the file/line for its mdbg record only.
    spki = CRYPTO_zalloc(size_of::<BarePubkey>(), ptr::null(), 0).cast::<BarePubkey>();
    if spki.is_null() {
        // SAFETY: `ret` is live and this call owns it.
        unsafe { ossl_slh_dsa_key_free(ret) };
        return ptr::null_mut();
    }

    // SAFETY: `spki` is a fresh zalloc'd structure; `end` is this frame's cursor.
    let parsed = unsafe {
        ASN1_item_d2i_ex(
            (&mut spki as *mut *mut BarePubkey).cast(),
            &mut end,
            der_len,
            &BARE_PUBKEY_ITEM,
            ptr::null_mut(),
            ptr::null(),
        )
    };
    if parsed.is_null() {
        // SAFETY: `ret`'s name is NUL-terminated.
        let name = unsafe { CStr::from_ptr(ossl_slh_dsa_key_get_name(ret)) }.to_string_lossy();
        // SAFETY: the message is NUL-terminated by `raise_msg`.
        unsafe {
            raise_msg(
                &err_sites::PROV_DECODE_DER2KEY_765,
                format!("malformed {name} public key ASN.1 encoding"),
            )
        };
        // SAFETY: `spki` is this frame's own and `ret` is live; both are freed here.
        unsafe {
            free_bare_pubkey(spki);
            ossl_slh_dsa_key_free(ret);
        };
        return ptr::null_mut();
    }

    // SAFETY: `spki` is live and its `pubkey` is the item's own; `end`/`der` are this frame's.
    let pubkey = unsafe { (*spki).pubkey };
    // SAFETY: `pubkey` is the item's own and `end`/`der` are this frame's pointers.
    let bad = unsafe {
        pubkey.is_null() || ((*pubkey).flags & 0x7) != 0 || end != (*der).add(der_len as usize)
    };
    if bad {
        // SAFETY: `ret`'s name is NUL-terminated.
        let name = unsafe { CStr::from_ptr(ossl_slh_dsa_key_get_name(ret)) }.to_string_lossy();
        // SAFETY: the message is NUL-terminated by `raise_msg`.
        unsafe {
            raise_msg(
                &err_sites::PROV_DECODE_DER2KEY_773,
                format!("malformed {name} public key ASN.1 encoding"),
            )
        };
        // SAFETY: `spki` is this frame's own and `ret` is live; both are freed here.
        unsafe {
            free_bare_pubkey(spki);
            ossl_slh_dsa_key_free(ret);
        };
        return ptr::null_mut();
    }

    // SAFETY: `spki`/`ret` are live; `ctx`'s evp_type is the row's own.
    if unsafe { OBJ_cmp(OBJ_nid2obj((*ctx).desc.evp_type), (*spki).algor.oid) } != 0 {
        // SAFETY: `ret`'s name is NUL-terminated.
        let name = unsafe { CStr::from_ptr(ossl_slh_dsa_key_get_name(ret)) }.to_string_lossy();
        // SAFETY: the message is NUL-terminated by `raise_msg`.
        unsafe {
            raise_msg(
                &err_sites::PROV_DECODE_DER2KEY_779,
                format!("unexpected algorithm OID for an {name} public key"),
            )
        };
        // SAFETY: `spki` is this frame's own and `ret` is live; both are freed here.
        unsafe {
            free_bare_pubkey(spki);
            ossl_slh_dsa_key_free(ret);
        };
        return ptr::null_mut();
    }

    // SAFETY: `pubkey` is live past the guard; `ret` is live.
    if unsafe { ossl_slh_dsa_set_pub(ret, (*pubkey).data, (*pubkey).length as usize) } == 0 {
        // SAFETY: `ret`'s name is NUL-terminated.
        let name = unsafe { CStr::from_ptr(ossl_slh_dsa_key_get_name(ret)) }.to_string_lossy();
        // SAFETY: the message is NUL-terminated by `raise_msg`.
        unsafe {
            raise_msg(
                &err_sites::PROV_DECODE_DER2KEY_786,
                format!("failed to parse {name} public key from the input data"),
            )
        };
        // SAFETY: `spki` is this frame's own and `ret` is live; both are freed here.
        unsafe {
            free_bare_pubkey(spki);
            ossl_slh_dsa_key_free(ret);
        };
        return ptr::null_mut();
    }

    // SAFETY: `spki` is this frame's own.
    unsafe { free_bare_pubkey(spki) };
    ret.cast::<c_void>()
}

// ---------------------------------------------------------------------------
// `MAKE_DECODER` — `decode_der2key.c:1223-1257`.
// ---------------------------------------------------------------------------

/// One `MAKE_DECODER(keytype_name, keytype, type, kind)` expansion: a `keytype_desc_st`, a
/// `newctx`/`does_selection` pair, and the `OSSL_DISPATCH` table.
macro_rules! make_decoder {
    ($desc:ident, $newctx:ident, $does:ident, $table:ident,
     $name:expr, $keymgmt:expr, $structure:expr, $evp_type:expr, $mask:expr,
     $priv:expr, $pubk:expr, $params:expr, $p8:expr, $pk8:expr,
     $check:expr, $adjust:expr, $free:expr) => {
        // The `$desc` identifiers mirror the authority's `kind##_##keytype##_desc` spelling, which
        // is lower-case for the kind prefix; the table itself is upper-case like every other.
        #[allow(non_upper_case_globals)]
        static $desc: KeytypeDesc = KeytypeDesc {
            keytype_name: $name,
            keymgmt: $keymgmt,
            structure_name: $structure,
            evp_type: $evp_type,
            selection_mask: $mask,
            d2i_private_key: $priv,
            d2i_public_key: $pubk,
            d2i_key_params: $params,
            d2i_pkcs8: $p8,
            d2i_pubkey: $pk8,
            check_key: $check,
            adjust_key: $adjust,
            free_key: $free,
        };

        /// The macro's `newctx` — `kind##_der2##keytype##_newctx`.
        ///
        /// # Safety
        /// The decoder `newctx` dispatch contract.
        #[allow(non_snake_case)] // mirrors the authority's `kind##_der2##keytype##_newctx`
        unsafe extern "C" fn $newctx(provctx: *mut c_void) -> *mut c_void {
            // SAFETY: `desc` is this row's own static and `provctx` is the caller's.
            unsafe { der2key_newctx(provctx, &$desc) }
        }

        /// The macro's `does_selection` — the unit's rule against the row's mask.
        ///
        /// # Safety
        /// The decoder `does_selection` dispatch contract.
        #[allow(non_snake_case)] // mirrors the authority's `kind##_der2##keytype##_does_selection`
        unsafe extern "C" fn $does(_provctx: *mut c_void, selection: c_int) -> c_int {
            der2key_check_selection(selection, &$desc)
        }

        /// `ossl_##kind##_der_to_##keytype##_decoder_functions[]`.
        pub(crate) static $table: [OsslDispatch; 8] = [
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_NEWCTX,
                function: $newctx as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_FREECTX,
                function: der2key_freectx as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_DOES_SELECTION,
                function: $does as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_DECODE,
                function: der2key_decode as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_EXPORT_OBJECT,
                function: der2key_export_object as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_SETTABLE_CTX_PARAMS,
                function: der2key_settable_ctx_params as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_FUNC_DECODER_SET_CTX_PARAMS,
                function: der2key_set_ctx_params as *mut c_void,
            },
            OsslDispatch {
                function_id: OSSL_DISPATCH_END,
                function: ptr::null_mut(),
            },
        ];
    };
}

/// One row, with the property placed beside the keymgmt and the structure/mask spelled by the kind.
macro_rules! dec {
    ($desc:ident, $newctx:ident, $does:ident, $table:ident, $name:expr, $keymgmt:expr, $prop:expr,
     $evp_type:expr, $structure:expr, $mask:expr, $priv:expr, $pubk:expr, $params:expr, $p8:expr,
     $pk8:expr, $check:expr, $adjust:expr, $free:expr) => {
        make_decoder!(
            $desc, $newctx, $does, $table, $name, $keymgmt, $structure, $evp_type, $mask, $priv,
            $pubk, $params, $p8, $pk8, $check, $adjust, $free
        );
    };
}

