/// One SLH-DSA variant's `PrivateKeyInfo` and `SubjectPublicKeyInfo` rows, with both dispatch
/// tables' identifiers passed explicitly (Rust macros cannot concatenate identifiers).
macro_rules! slh_pair {
    ($pdesc:ident, $pnc:ident, $pdoes:ident, $ptbl:ident,
     $sdesc:ident, $snc:ident, $sdoes:ident, $stbl:ident,
     $name:expr, $evp:expr, $keymgmt:expr) => {
        dec!(
            $pdesc,
            $pnc,
            $pdoes,
            $ptbl,
            $name,
            $keymgmt,
            P_DEF_P8,
            $evp,
            c"PrivateKeyInfo".as_ptr(),
            PRIV,
            None,
            None,
            None,
            Some(slh_dsa_d2i_pkcs8),
            None,
            None,
            None,
            Some(free_slh_dsa)
        );
        dec!(
            $sdesc,
            $snc,
            $sdoes,
            $stbl,
            $name,
            $keymgmt,
            P_DEF_SPKI,
            $evp,
            c"SubjectPublicKeyInfo".as_ptr(),
            PUB,
            None,
            None,
            None,
            None,
            Some(slh_dsa_d2i_pubkey),
            None,
            None,
            Some(free_slh_dsa)
        );
    };
}

