#[cfg(test)]
mod tests {
    use super::*;

    /// Every table is the authority's seven-slot shape and terminates.
    #[test]
    fn each_decoder_table_is_the_authoritys_seven_slot_shape() {
        for fns in [&DH_FUNCTIONS[..], &EC_FUNCTIONS[..], &RSA_FUNCTIONS[..]] {
            let mut i = 0;
            let mut seen = [false; 7];
            let mut unexpected = 0;
            // SAFETY: each table is terminated and each read is within it.
            unsafe {
                while (*fns.as_ptr().add(i)).function_id != OSSL_DISPATCH_END {
                    match (*fns.as_ptr().add(i)).function_id {
                        OSSL_FUNC_DECODER_NEWCTX => seen[0] = true,
                        OSSL_FUNC_DECODER_FREECTX => seen[1] = true,
                        OSSL_FUNC_DECODER_DOES_SELECTION => seen[2] = true,
                        OSSL_FUNC_DECODER_DECODE => seen[3] = true,
                        OSSL_FUNC_DECODER_EXPORT_OBJECT => seen[4] = true,
                        OSSL_FUNC_DECODER_SETTABLE_CTX_PARAMS => seen[5] = true,
                        OSSL_FUNC_DECODER_SET_CTX_PARAMS => seen[6] = true,
                        _ => unexpected += 1,
                    }
                    i += 1;
                }
            }
            assert_eq!(unexpected, 0, "a decoder table carries an unexpected slot");
            assert!(seen.iter().all(|&s| s), "a decoder table is missing a slot");
            assert_eq!(i, 7);
        }
    }

    /// The selection rule is the authority's: an empty selection is accepted, and the first of the
    /// three levels the caller asks for is answered by the mask.
    #[test]
    fn the_selection_rule_is_the_authoritys() {
        assert_eq!(der2key_check_selection(0, &ec_priv_info_desc), 1);
        assert_eq!(
            der2key_check_selection(OSSL_KEYMGMT_SELECT_PRIVATE_KEY, &ec_priv_info_desc),
            1
        );
        assert_eq!(
            der2key_check_selection(OSSL_KEYMGMT_SELECT_PUBLIC_KEY, &ec_priv_info_desc),
            0
        );
        assert_eq!(
            der2key_check_selection(OSSL_KEYMGMT_SELECT_PUBLIC_KEY, &ec_spki_desc),
            1
        );
        assert_eq!(
            der2key_check_selection(OSSL_KEYMGMT_SELECT_ALL_PARAMETERS, &dh_spki_desc),
            0
        );
    }

    /// The combined table is 74 rows plus a terminator, the epki row is last, and the two provider
    /// tables differ only in the provider prefix.
    #[test]
    fn the_combined_tables_are_the_seventy_rows_and_mirror_across_providers() {
        assert_eq!(DEFLT_DECODERS.len(), 75, "74 rows plus the terminator");
        assert_eq!(BASE_DECODERS.len(), 75);
        // SAFETY: the terminator row's name is null.
        assert_eq!(DEFLT_DECODERS[74].algorithm_names, ptr::null());
        assert_eq!(
            // SAFETY: row 73 is the epki row.
            DEFLT_DECODERS[73].implementation,
            // SAFETY: the epki table's own address.
            ENCRYPTED_PRIVATE_KEY_INFO_DER_FUNCTIONS
                .as_ptr()
                .cast::<c_void>()
        );
        // SAFETY: every row's two C strings are statics this module wrote.
        unsafe {
            for i in 0..74 {
                assert_eq!(
                    DEFLT_DECODERS[i].algorithm_names,
                    BASE_DECODERS[i].algorithm_names
                );
                assert_eq!(
                    DEFLT_DECODERS[i].implementation,
                    BASE_DECODERS[i].implementation
                );
                let d = CStr::from_ptr(DEFLT_DECODERS[i].property_definition).to_bytes();
                let b = CStr::from_ptr(BASE_DECODERS[i].property_definition).to_bytes();
                assert!(d.starts_with(b"provider=default,"), "row {i}");
                assert!(b.starts_with(b"provider=base,"), "row {i}");
                assert_eq!(
                    &d[b"provider=default".len()..],
                    &b[b"provider=base".len()..],
                    "row {i}"
                );
            }
        }
    }

    /// The SM2 rows are the only `fips=no` DER rows.
    #[test]
    fn sm2_is_the_only_non_fips_row() {
        // SAFETY: the property is a static C string.
        let p = unsafe { CStr::from_ptr(P_DEF_SM2_P8) }.to_bytes();
        assert!(p.starts_with(b"provider=default,fips=no,"));
        // SAFETY: as above.
        let q = unsafe { CStr::from_ptr(P_DEF_P8) }.to_bytes();
        assert!(q.starts_with(b"provider=default,fips=yes,"));
    }
}
